begin;

create table public.arena_alliance_emblem_catalog(
 id text primary key check(id~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),name text not null,image_path text not null,
 tier text not null check(tier in('free','gems','pro')),gem_price integer check(gem_price is null or gem_price between 1 and 10000),
 sort_order integer not null unique,active boolean not null default true,check((tier='gems')=(gem_price is not null))
);
insert into public.arena_alliance_emblem_catalog(id,name,image_path,tier,gem_price,sort_order)values
('pomba-da-alianca','Pomba da Aliança','/images/arena/alliance-emblems-v63/pomba-da-alianca.webp','free',null,1),
