('trigo-da-colheita','Trigo da Colheita','/images/arena/alliance-emblems-v63/trigo-da-colheita.webp','free',null,3),
('monte-da-promessa','Monte da Promessa','/images/arena/alliance-emblems-v63/monte-da-promessa.webp','free',null,4),
('leao-de-juda','Leão de Judá','/images/arena/alliance-emblems-v63/leao-de-juda.webp','gems',500,5),
('arca-sobre-as-aguas','Arca sobre as Águas','/images/arena/alliance-emblems-v63/arca-sobre-as-aguas.webp','gems',450,6),
('trombetas-de-jerico','Trombetas de Jericó','/images/arena/alliance-emblems-v63/trombetas-de-jerico.webp','gems',550,7),
('fogo-do-carmelo','Fogo do Carmelo','/images/arena/alliance-emblems-v63/fogo-do-carmelo.webp','gems',650,8),
('coroa-das-doze-estrelas','Coroa das Doze Estrelas','/images/arena/alliance-emblems-v63/coroa-das-doze-estrelas.webp','pro',null,9),
('portoes-de-safira','Portões de Safira','/images/arena/alliance-emblems-v63/portoes-de-safira.webp','pro',null,10),
('espada-dos-serafins','Espada dos Serafins','/images/arena/alliance-emblems-v63/espada-dos-serafins.webp','pro',null,11),
